// generated from the original (re/notes_flight.md): HTS = 128x128 heights (Int16), SHD = 128x128 vertex shade (Int16) (table 0x105ff8, built by 0x1d450/0x1d36c);
// PATH = per rendered frame (10 ticks) float64 x4 objects (camera, ship0..2) x [pos3 (the node's int32 position), matrix9 (the node's doubles)] read at each call of the render 0x286ac of the real run (record i = iteration i+2).
const d=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0)).buffer;
export const HTS=new Int16Array(d(''));
export const SHD=new Int16Array(d(''));
export const PATH=new Float64Array(d(''));
export const NF=565;
